package ai.interviewiq.api.repository; import ai.interviewiq.api.entity.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import java.util.*; public interface InterviewSessionRepository extends JpaRepository<InterviewSession,Long>{ @EntityGraph(attributePaths={"company","jobRole","difficultyLevel","interviewTemplate","questions"}) Optional<InterviewSession> findByIdAndUserId(Long id,Long userId); Page<InterviewSession> findByUserIdAndStatus(Long userId,InterviewStatus status,Pageable pageable); Page<InterviewSession> findByUserId(Long userId,Pageable pageable); }
